INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 1, "2030/01/01 14:59:59", 3.414, 190801, 0.0, 1, "カリン", 1, 1000001, 62, "2025/01/31 12:00:00", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 1, "2030/01/01 14:59:59", 3.099, 190801, 0.0, 1, "カリン", 2, 1000002, 62, "2025/01/31 12:00:00", "ミッションをクリアして、\n報酬をゲットしましょう！", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 1, "2030/01/01 14:59:59", 2.801, 190801, 0.0, 1, "カリン", 3, 1000003, 63, "2025/01/31 12:00:00", "受け取ることができる\n報酬があるようです\n確認してみてください", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 1, "2030/01/01 14:59:59", 0.0, 190801, 0.0, 2, "カリン", 4, 1000004, 63, "2025/01/31 12:00:00", "報酬がもらえますよ！\nチェックしてみてください", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 1, "2030/01/01 14:59:59", 2.12, 190801, 0.0, 2, "カリン", 5, 1000005, 64, "2025/01/31 12:00:00", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 1, "2030/01/01 14:59:59", 1.68, 190801, 0.0, 1, "カリン", 6, 1000006, 64, "2025/01/31 12:00:00", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 1, "2030/01/01 14:59:59", 2.33, 190801, 0.0, 2, "カリン", 7, 1000007, 64, "2025/01/31 12:00:00", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 10201, "2030/01/01 14:59:59", 5.18, 133701, -6.0, 3, "ラビリスタ", 101, 1020101, 61, "2025/01/31 12:00:00", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10201, "2030/01/01 14:59:59", 8.77, 133901, -2.0, 1, "クリスティーナ", 201, 1020102, 61, "2025/01/31 12:00:00", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10201, "2030/01/01 14:59:59", 15.5, 133801, 0.0, 6, "ネネカ", 301, 1020103, 61, "2025/01/31 12:00:00", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 10202, "2030/01/01 14:59:59", 9.061, 134301, 0.0, 2, "ランファ", 101, 1020201, 61, "2025/02/28 12:00:00", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10202, "2030/01/01 14:59:59", 7.699, 134401, 0.0, 1, "チカ", 201, 1020202, 61, "2025/02/28 12:00:00", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10203, "2030/01/01 14:59:59", 8.595, 134601, 0.0, 1, "アオイ", 101, 1020301, 61, "2025/03/31 12:00:00", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10203, "2030/01/01 14:59:59", 7.758, 134501, 0.0, 1, "クローチェ", 201, 1020302, 61, "2025/03/31 12:00:00", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, 10204, "2030/01/01 14:59:59", 7.0, 132302, 0.0, 2, "ルイズマリー", 101, 1020401, 61, "2025/04/30 12:00:00", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10204, "2030/01/01 14:59:59", 7.904, 132402, 0.0, 1, "イロハ", 201, 1020402, 61, "2025/04/30 12:00:00", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10204, "2030/01/01 14:59:59", 8.487, 132502, 0.0, 4, "ソノ", 301, 1020403, 61, "2025/04/30 12:00:00", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10205, "2030/01/01 14:59:59", 8.763, 134901, 0.0, 1, "カノン", 101, 1020502, 61, "2025/05/31 12:00:00", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10205, "2030/01/01 14:59:59", 6.417, 134801, 0.0, 1, "ツムギ", 201, 1020503, 61, "2025/05/31 12:00:00", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 10206, "2030/01/01 14:59:59", 10.335, 135001, 0.0, 3, "エリス", 101, 1020601, 61, "2025/06/30 12:00:00", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 10206, "2030/01/01 14:59:59", 6.281, 135101, 0.0, 2, "シェフィ", 201, 1020602, 61, "2025/06/30 12:00:00", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10206, "2030/01/01 14:59:59", 12.244, 135201, 0.0, 1, "プレシア", 301, 1020603, 61, "2025/06/30 12:00:00", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8, 10207, "2030/01/01 14:59:59", 6.339, 135301, 0.0, 2, "クリア", 101, 1020701, 61, "2025/07/31 12:00:00", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9, 10207, "2030/01/01 14:59:59", 8.184, 135401, 0.0, 7, "アネモネ", 201, 1020702, 61, "2025/07/31 12:00:00", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10208, "2030/01/01 14:59:59", 3.906, 129101, 0.0, 9, "アイラ", 101, 1020801, 61, "2025/08/31 12:00:00", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10208, "2030/01/01 14:59:59", 14.465, 129201, 0.0, 1, "シナツ", 201, 1020802, 61, "2025/08/31 12:00:00", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10208, "2030/01/01 14:59:59", 8.662, 100101, 0.0, 4, "ヒヨリ", 301, 1020803, 61, "2025/08/31 12:00:00", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10208, "2030/01/01 14:59:59", 10.915, 100301, 0.0, 1, "レイ", 401, 1020804, 61, "2025/08/31 12:00:00", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 10209, "2030/01/01 14:59:59", 6.042, 135802, 0.0, 1, "ユキノ", 101, 1020901, 61, "2025/09/30 12:00:00", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10209, "2030/01/01 14:59:59", 9.402, 135903, 0.0, 4, "サツキ", 201, 1020902, 61, "2025/09/30 12:00:00", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10209, "2030/01/01 14:59:59", 8.16, 136902, 0.0, 8, "ルルィ", 301, 1020903, 61, "2025/09/30 12:00:00", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10210, "2030/01/01 14:59:59", 5.0, 137401, 0.0, 3, "カスミ", 101, 1021001, 61, "2025/10/31 12:00:00", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10210, "2030/01/01 14:59:59", 8.12, 136001, 0.0, 4, "アラクネ", 201, 1021002, 61, "2025/10/31 12:00:00", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10210, "2030/01/01 14:59:59", 6.386, 136202, 0.0, 4, "ナーナ", 301, 1021003, 61, "2025/10/31 12:00:00", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 10211, "2030/01/01 14:59:59", 7.438, 136402, 0.0, 3, "ユイ", 101, 1021101, 61, "2025/11/30 12:00:00", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 10211, "2030/01/01 14:59:59", 8.35, 136302, 0.0, 1, "ミソラ", 201, 1021102, 61, "2025/11/30 12:00:00", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10212, "2030/01/01 14:59:59", 5.0, 136501, 0.0, 1, "シズル", 101, 1021201, 61, "2025/12/31 12:00:00", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10212, "2030/01/01 14:59:59", 5.25, 137902, 0.0, 1, "リノ", 201, 1021202, 61, "2025/12/31 12:00:00", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10212, "2030/01/01 14:59:59", 7.5, 106801, 0.0, 1, "ラビリスタ", 301, 1021203, 61, "2025/12/31 12:00:00", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10213, "2030/01/01 14:59:59", 8.204, 126501, 0.0, 1, "ライラエル", 101, 1021301, 61, "2026/01/31 12:00:00", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10213, "2030/01/01 14:59:59", 7.176, 129701, 0.0, 1, "ネフィ＝ネラ", 201, 1021302, 61, "2026/01/31 12:00:00", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 10213, "2030/01/01 14:59:59", 8.602, 133101, 0.0, 1, "ヴァイオレット", 301, 1021303, 61, "2026/01/31 12:00:00", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10213, "2030/01/01 14:59:59", 10.14, 138101, 0.0, 1, "ライラエル", 102, 1021304, 61, "2026/02/06 12:00:00", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 10213, "2030/01/01 14:59:59", 10.152, 138201, 0.0, 1, "ネフィ＝ネラ", 202, 1021305, 61, "2026/02/06 12:00:00", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10213, "2030/01/01 14:59:59", 9.688, 138001, 0.0, 4, "ヴァイオレット", 302, 1021306, 61, "2026/02/06 12:00:00", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10213, "2030/01/01 14:59:59", 5.928, 138301, 0.0, 2, "ペコリーヌ", 401, 1021307, 61, "2026/02/12 12:00:00", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10214, "2030/01/01 14:59:59", 9.19, 138702, 0.0, 4, "ワカナ", 101, 1021401, 61, "2026/02/28 12:00:00", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10214, "2030/01/01 14:59:59", 8.724, 138802, 0.0, 1, "シオリ", 201, 1021402, 61, "2026/02/28 12:00:00", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10215, "2030/01/01 14:59:59", 7.758, 138902, 0.0, 4, "グレイス", 101, 1021501, 61, "2026/03/31 12:00:00", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 10215, "2030/01/01 14:59:59", 6.375, 139002, 0.0, 6, "キョウカ", 201, 1021502, 61, "2026/03/31 12:00:00", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10215, "2030/01/01 14:59:59", 6.173, 136902, 0.0, 6, "ルルィ", 301, 1021503, 61, "2026/03/31 12:00:00", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10216, "2030/01/01 14:59:59", 4.202, 139202, 0.0, 6, "ミホ", 101, 1021601, 61, "2026/04/30 12:00:00", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10216, "2030/01/01 14:59:59", 2.842, 139302, 0.0, 6, "マホ", 201, 1021602, 61, "2026/04/30 12:00:00", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10216, "2030/01/01 14:59:59", 4.598, 139402, 0.0, 4, "エリカ", 301, 1021603, 61, "2026/04/30 12:00:00", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10217, "2030/01/01 14:59:59", 6.533, 125802, 0.0, 4, "リリ", 101, 1021701, 61, "2026/05/31 12:00:00", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10217, "2030/01/01 14:59:59", 5.0, 126102, 0.0, 3, "プレシア", 301, 1021702, 61, "2026/05/31 12:00:00", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 10217, "2030/01/01 14:59:59", 5.214, 126002, 0.0, 3, "クリア", 201, 1021703, 61, "2026/05/31 12:00:00", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10217, "2030/01/01 14:59:59", 8.781, 139501, 0.0, 1, "リリ", 102, 1021704, 61, "2026/05/31 12:00:00", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10217, "2030/01/01 14:59:59", 6.529, 139601, 0.0, 2, "クリア", 202, 1021705, 61, "2026/05/31 12:00:00", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10217, "2030/01/01 14:59:59", 3.195, 139701, 0.0, 3, "プレシア", 302, 1021706, 61, "2026/05/31 12:00:00", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10218, "2030/01/01 14:59:59", 12.43, 139902, 0.0, 2, "ルイズマリー", 101, 1021801, 61, "2026/06/30 12:00:00", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10218, "2030/01/01 14:59:59", 6.35, 140001, 0.0, 2, "クレジッタ", 201, 1021802, 61, "2026/06/30 12:00:00", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 10219, "2030/01/01 14:59:59", 10.23, 140102, 0.0, 1, "フブキ", 101, 1021901, 61, "2026/07/31 12:00:00", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 10219, "2030/01/01 14:59:59", 5.584, 140201, 0.0, 1, "ヴァンピィ", 201, 1021902, 61, "2026/07/31 12:00:00", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10220, "2030/01/01 14:59:59", 2.8, 126401, 0.0, 6, "クローチェ", 201, 1022001, 61, "2026/08/31 12:00:00", "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10220, "2030/01/01 14:59:59", 8.9, 127802, 0.0, 4, "ヴルム", 101, 1022002, 61, "2026/08/31 12:00:00", "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10220, "2030/01/01 14:59:59", 4.49, 140602, 0.0, 2, "クローチェ", 202, 1022003, 61, "2026/08/31 12:00:00", "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 10220, "2030/01/01 14:59:59", 9.42, 140501, 0.0, 1, "ヴルム", 102, 1022004, 61, "2026/08/31 12:00:00", "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 10220, "2030/01/01 14:59:59", 7.0, 140402, 0.0, 4, "リーザ", 301, 1022005, 61, "2026/08/31 12:00:00", "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 2, "2030/01/01 14:59:59", 3.414, 190805, 0.0, 1, "カリン", 1, 2000001, 62, "2026/04/10 12:00:00", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 2, "2030/01/01 14:59:59", 3.099, 190805, 0.0, 1, "カリン", 2, 2000002, 62, "2026/04/10 12:00:00", "ミッションをクリアして、\n報酬をゲットしましょう！", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 2, "2030/01/01 14:59:59", 2.801, 190805, 0.0, 1, "カリン", 3, 2000003, 63, "2026/04/10 12:00:00", "受け取ることができる\n報酬があるようです\n確認してみてください", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 2, "2030/01/01 14:59:59", 0.0, 190805, 0.0, 2, "カリン", 4, 2000004, 63, "2026/04/10 12:00:00", "報酬がもらえますよ！\nチェックしてみてください", -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 2, "2030/01/01 14:59:59", 2.12, 190805, 0.0, 2, "カリン", 5, 2000005, 64, "2026/04/10 12:00:00", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 2, "2030/01/01 14:59:59", 1.68, 190805, 0.0, 1, "カリン", 6, 2000006, 64, "2026/04/10 12:00:00", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 2, "2030/01/01 14:59:59", 2.33, 190805, 0.0, 2, "カリン", 7, 2000007, 64, "2026/04/10 12:00:00", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", -363.0);
